}
```

With your own job, methods and time zones, and an API call:

```tsx
"use client"

import { CronJobForm, type CronJobFormValues } from "@/components/cron-job-form"

export function Example({ onDone }: { onDone: () => void }) {
  async function createJob(values: CronJobFormValues) {
    const response = await fetch("/api/cron-jobs", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(values),
    })
    // a throw keeps the form as it is and shows "Couldn't create the job. Try again."
    if (!response.ok) throw new Error(`Create failed: ${response.status}`)
  }

  return (
    <CronJobForm
      title="New scheduled task"
      badge={null}
      methods={["GET", "POST"]}
      timezones={["UTC", "Europe/Amsterdam", "America/Chicago"]}
      defaultValues={{
        name: "Invoice reminders",
        method: "GET",
        path: "/api/tasks/reminders",
        schedule: "daily",
        expression: "30 7 * * *",
        timezone: "Europe/Amsterdam",
      }}
      onSubmit={createJob}
      onCancel={onDone}
      onClose={onDone}
    />
  )
}
```

