Your own departments and an async `onSubmit` that reports its progress to the status bar:

```tsx
"use client"


import { RetroOsAccountForm, type RetroOsAccountFormValues, type RetroOsAccountSubmitHelpers } from "@/components/retro-os-account-form"

async function createUser(values: RetroOsAccountFormValues, { action, progress }: RetroOsAccountSubmitHelpers) {
  progress(10, "Creating account...")
  const body = new FormData()
  for (const [key, value] of Object.entries(values)) if (value !== null) body.append(key, value instanceof File ? value : String(value))
  const response = await fetch(`/api/users?apply=${action === "apply"}`, { method: "POST", body })
  // a throw keeps the dialog and shows "Account not created. Try again." in red
  if (!response.ok) throw new Error(`Create failed: ${response.status}`)
  progress(70, "Creating home folder...")
  await fetch(`/api/users/${values.userName}/home`, { method: "POST" })
}

export function Example({ onDone }: { onDone: () => void }) {
  return (
    <RetroOsAccountForm
      title="Add Team Member"
      departments={[
        { value: "studio", label: "Studio" },
        { value: "kitchen", label: "Kitchen" },
        { value: "front", label: "Front of house" },
      ]}
      takenUserNames={["admin", "owner", "rina"]}
      homeFolder={(userName) => `/home/${userName}`}
      defaultValues={{ fullName: "", userName: "", email: "", password: "", department: "studio" }}
      onSubmit={createUser}
      onCancel={onDone}
      onClose={onDone}
    />
  )
}
```

