With your own wallet, networks and address book, and an API call:

```tsx
"use client"

import {
  TokenTransferForm,
  type TokenTransferFormValues,
  type TokenTransferNetwork,
  type TokenTransferRecipient,
  type TokenTransferToken,
} from "@/components/token-transfer-form"

const tokens: TokenTransferToken[] = [
  { symbol: "USDC", name: "USD Coin", glyph: "$", balance: 812.4, usdPrice: 1, contract: "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913", verified: true },
  { symbol: "EURC", name: "Euro Coin", glyph: "€", balance: 120, usdPrice: 1.08 },
]

const networks: TokenTransferNetwork[] = [
  { value: "base", label: "Base", feeSymbol: "ETH", fee: 0.00004 },
  { value: "polygon", label: "Polygon", feeSymbol: "POL", fee: 0.02 },
]

const recipients: TokenTransferRecipient[] = [
  { address: "0x4b20993bc481177ec7e8f571cecae8a9e22c02db", name: "studio.acme.eth", note: "Verified yesterday" },
]

export function Example({ onClose }: { onClose: () => void }) {
  async function send(values: TokenTransferFormValues) {
    const response = await fetch("/api/transfers", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(values),
    })
    // a throw keeps the sheet as it is and shows "The transfer didn’t go through. Try again."
    if (!response.ok) throw new Error(`Transfer failed: ${response.status}`)
  }

  return (
    <TokenTransferForm
      title="Send"
      tokens={tokens}
      networks={networks}
      recipients={recipients}
      defaultValues={{ token: "USDC", network: "base", recipient: recipients[0].address, amount: 25, speed: "fast" }}
      learnMoreLabel="Transfers are final — read how they work"
      onLearnMore={() => window.open("/help/transfers", "_blank")}
      onSubmit={send}
      onClose={onClose}
    />
  )
}
```

